# Ollama's default context is tiny (2-4k tokens) and silently cuts off the prompt,
# which is the usual reason a model "ignores" an uploaded file.
NUM_CTX = int(os.environ.get("STUDIORA_NUM_CTX", "8192"))

DOC_NUM_CTX = int(os.environ.get("STUDIORA_DOC_NUM_CTX", "12288"))   # bigger window for documents
DOC_MAX_TOKENS = int(os.environ.get("STUDIORA_DOC_MAX_TOKENS", "6000"))

CHUNK_SIZE = 900
CHUNK_OVERLAP = 120
TOP_K = 6
WHOLE_DOC_CHARS = 14000      # documents up to this size are sent whole
CONTEXT_CHARS = 12000        # max document text placed in a prompt
HISTORY_LIMIT = 12           # message pairs of history sent to the model
