# --------------------------------------------------------------------------
# Generation jobs (run on the server, independent of the browser connection)
# --------------------------------------------------------------------------
class Job:
    def __init__(self, chat_id, sources, kind="chat", status=""):
        self.chat_id = chat_id
        self.sources = sources
        self.kind = kind            # chat | doc | diagram | mcq | instant
        self.status = status        # short human text shown under the orb ("Drawing your diagram…")
        self.message_id = None
        self.text = ""
        self.done = False
        self.cancel = False
        self.cond = threading.Condition()

    def push(self, tok):
        with self.cond:
            self.text += tok
            self.cond.notify_all()

    def set_status(self, status):
        with self.cond:
            self.status = status
            self.cond.notify_all()

    def finish(self):
        with self.cond:
            self.done = True
            self.cond.notify_all()


JOBS = {}
JOBS_LOCK = threading.Lock()


def thread_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def execute_job(job, work):
    """Run work(job) on a background thread, then save whatever it produced as the assistant message."""
    try:
        work(job)
    except requests.exceptions.RequestException:
        job.push(
            "I couldn't reach the local model. Make sure **Ollama** is running "
            "(`ollama serve`) and that the model is installed (`ollama pull qwen2.5:7b`)."
        )
    except Exception as exc:  # noqa: BLE001
        job.push(f"⚠️ {exc}")
    finally:
        text = job.text.strip()
        try:
            conn = thread_db()
            if text:
                cur = conn.execute(
                    "INSERT INTO messages (chat_id, role, content, sources) VALUES (?, 'assistant', ?, ?)",
                    (job.chat_id, text, json.dumps(job.sources) if job.sources else None),
                )
                job.message_id = cur.lastrowid
                conn.execute("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?", (job.chat_id,))
            conn.commit()
            conn.close()
        except sqlite3.Error:
            pass  # chat was deleted while generating
        with JOBS_LOCK:
            JOBS.pop(job.chat_id, None)
        job.finish()


def chat_work(messages, model):
    """Stream a normal answer from Ollama into the job."""
    def work(job):
        with requests.post(
            f"{OLLAMA_URL}/api/chat",
            json={"model": model, "messages": messages, "stream": True, "options": {"num_ctx": NUM_CTX}},
            stream=True,
            timeout=(5, 600),
        ) as resp:
            if resp.status_code == 404:
                job.push(f"The model `{model}` isn't installed. Run `ollama pull {model}` and try again.")
                return
            resp.raise_for_status()
            for line in resp.iter_lines():
                if job.cancel:
                    break
                if not line:
                    continue
                obj = json.loads(line)
                if obj.get("error"):
                    job.push(f"⚠️ {obj['error']}")
                    break
                tok = obj.get("message", {}).get("content", "")
                if tok:
                    job.push(tok)
                if obj.get("done"):
                    break
    return work


# ---- JSON-mode helper (structured output for diagrams / documents / quizzes) ----
_FENCE_RE = re.compile(r"^```(?:json)?\s*|\s*```$", re.I)
_TRAILING_COMMA_RE = re.compile(r",\s*([\]}])")


def parse_llm_json(text):
    t = _FENCE_RE.sub("", (text or "").strip()).strip()
    a, b = t.find("{"), t.rfind("}")
    if a != -1 and b > a:
        t = t[a:b + 1]
    try:
        return json.loads(t, strict=False)
    except json.JSONDecodeError:
        return json.loads(_TRAILING_COMMA_RE.sub(r"\1", t), strict=False)


def llm_json(prompt, model, num_predict=2000, num_ctx=None, temperature=0.4, tries=2):
    last = None
    for _ in range(tries):
        r = requests.post(
            f"{OLLAMA_URL}/api/chat",
            json={"model": model, "stream": False, "format": "json",
                  "messages": [{"role": "user", "content": prompt}],
                  "options": {"num_ctx": num_ctx or NUM_CTX, "num_predict": num_predict, "temperature": temperature}},
            timeout=(5, 900),
        )
        if r.status_code == 404:
            raise RuntimeError(f"The model `{model}` isn't installed. Run `ollama pull {model}`.")
        r.raise_for_status()
        try:
            return parse_llm_json(r.json().get("message", {}).get("content", ""))
        except (ValueError, KeyError) as exc:
            last = exc
    raise ValueError(f"the model did not return valid JSON ({last})")


def sse(event, payload):
    return f"event: {event}\ndata: {json.dumps(payload)}\n\n"


