@app.delete("/api/chats/<int:chat_id>")
@login_required
def delete_chat(chat_id):
    if not own_chat(chat_id):
        return jsonify(error="Not found"), 404
    job = JOBS.get(chat_id)
    if job:
        job.cancel = True
    db = get_db()
    for f in db.execute("SELECT stored_name FROM chat_files WHERE chat_id = ?", (chat_id,)):
        _remove_file(f["stored_name"])
    db.execute("DELETE FROM chats WHERE id = ?", (chat_id,))
    db.commit()
    return jsonify(ok=True)


@app.get("/api/chats/<int:chat_id>/messages")
@login_required
def get_messages(chat_id):
    if not own_chat(chat_id):
        return jsonify(error="Not found"), 404
    rows = get_db().execute(
        "SELECT id, role, content, sources, attachments, meta FROM messages WHERE chat_id = ? ORDER BY id",
        (chat_id,),
    ).fetchall()
    out = []
    for r in rows:
        d = dict(r)
        d["sources"] = json.loads(d["sources"]) if d["sources"] else []
        d["attachments"] = json.loads(d["attachments"]) if d["attachments"] else []
        d["meta"] = json.loads(d["meta"]) if d["meta"] else {}
        out.append(d)
    return jsonify(messages=out, generating=chat_id in JOBS)


@app.delete("/api/chats/<int:chat_id>/messages")
@login_required
def clear_messages(chat_id):
    if not own_chat(chat_id):
        return jsonify(error="Not found"), 404
    if chat_id in JOBS:
        return jsonify(error="Wait for the current answer to finish (or stop it) first"), 409
    db = get_db()
    db.execute("DELETE FROM messages WHERE chat_id = ?", (chat_id,))
    db.commit()
    return jsonify(ok=True)


# --------------------------------------------------------------------------
# Documents
# --------------------------------------------------------------------------
def _remove_file(stored_name):
    try:
        os.remove(os.path.join(UPLOAD_DIR, stored_name))
    except OSError:
        pass


def extract_pages(path, ext):
    """Return a list of (page_number, text)."""
    if ext == "pdf":
        try:
            import fitz  # PyMuPDF

            with fitz.open(path) as doc:
                return [(i + 1, p.get_text()) for i, p in enumerate(doc)]
        except ImportError:
            from pypdf import PdfReader

            reader = PdfReader(path)
            return [(i + 1, p.extract_text() or "") for i, p in enumerate(reader.pages)]
    if ext == "docx":
        import docx

        d = docx.Document(path)
        parts = [p.text for p in d.paragraphs]
        for table in d.tables:
            for row in table.rows:
                parts.append(" | ".join(c.text.strip() for c in row.cells))
        return [(1, "\n".join(parts))]
    for enc in ("utf-8", "utf-16", "latin-1"):
        try:
            with open(path, "r", encoding=enc) as fh:
                return [(1, fh.read())]
        except (UnicodeError, OSError):
            continue
    return [(1, "")]


_HEAD_RE = re.compile(r"^(?:\d+(?:\.\d+)*[.)]?\s+)?[A-Z][^\n]{2,70}$")


def _is_heading(line):
    line = line.strip()
    if not line or len(line) > 70 or line.endswith((".", ",", ";", ":")) and not line.isupper():
        return False
    words = line.split()
    if len(words) > 10:
        return False
    return line.isupper() or bool(re.match(r"^(chapter|unit|module|section|topic)\b|^\d+(\.\d+)*[.)]?\s+[A-Z]", line, re.I)) \
        or (_HEAD_RE.match(line) and sum(w[:1].isupper() for w in words) >= max(1, len(words) * 0.6) and len(words) <= 7)


def chunk_text(text):
    """Paragraph-aware chunks that remember the section heading they sit under."""
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    lines = [ln.strip() for ln in text.split("\n")]
    units, heading = [], ""          # (heading, paragraph)
    buf = []
    def flush():
        if buf:
            units.append((heading, " ".join(buf)))
            buf.clear()
    for ln in lines:
        if not ln:
            flush()
        elif _is_heading(ln):
            flush()
            heading = ln
            units.append((heading, ln))
        else:
            buf.append(ln)
            if len(" ".join(buf)) > CHUNK_SIZE * 0.8 and ln.endswith("."):
                flush()
    flush()

    out, cur, cur_head = [], "", ""
    def emit():
        nonlocal cur
        if cur.strip():
            prefix = f"[{cur_head}]\n" if cur_head and not cur.startswith(cur_head) else ""
            out.append(prefix + cur.strip())
        cur = ""
    for head, para in units:
        pieces = [para]
        if len(para) > CHUNK_SIZE:        # very long paragraph: split on sentences
            pieces, p = [], ""
            for sent in re.split(r"(?<=[.!?])\s+", para):
                if len(p) + len(sent) > CHUNK_SIZE and p:
                    pieces.append(p)
                    p = ""
                p += (" " if p else "") + sent
            if p:
                pieces.append(p)
        for piece in pieces:
            if cur and (len(cur) + len(piece) > CHUNK_SIZE or (head != cur_head and len(cur) > CHUNK_SIZE * 0.4)):
                tail = cur[-CHUNK_OVERLAP:] if head == cur_head else ""
                emit()
                cur = tail
            if not cur:
                cur_head = head
            cur += ("\n" if cur else "") + piece
    emit()
    return out


def normalize(vec):
    n = math.sqrt(sum(x * x for x in vec)) or 1.0
    return [x / n for x in vec]


def embed_texts(texts):
    """Vectors from Ollama, or None if the embedding model is unavailable."""
    try:
        r = requests.post(f"{OLLAMA_URL}/api/embed", json={"model": EMBED_MODEL, "input": texts}, timeout=120)
        if r.ok:
            vecs = r.json().get("embeddings")
            if vecs and len(vecs) == len(texts):
                return vecs
    except (requests.exceptions.RequestException, ValueError):
        pass
    return None


