@app.post("/api/chats/<int:chat_id>/upload")
@login_required
def upload(chat_id):
    if not own_chat(chat_id):
        return jsonify(error="Not found"), 404
    f = request.files.get("file")
    if not f or not f.filename:
        return jsonify(error="No file provided"), 400
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in ALLOWED_EXT:
        return jsonify(error="Supported types: PDF, DOCX, TXT, MD, CSV"), 400
    stored = f"chat{chat_id}_{uuid.uuid4().hex[:8]}.{ext}"
    path = os.path.join(UPLOAD_DIR, stored)
    f.save(path)
    try:
        pages = extract_pages(path, ext)
    except Exception as exc:  # noqa: BLE001
        _remove_file(stored)
        return jsonify(error=f"Could not read that file: {exc}"), 422
    rows, idx = [], 0
    for pg, txt in pages:
        for c in chunk_text(txt):
            rows.append((pg, idx, c))
            idx += 1
    if not rows:
        _remove_file(stored)
        msg = ("This PDF has no selectable text (it looks like a scan). Run OCR on it first."
               if ext == "pdf" else "No readable text found in that file")
        return jsonify(error=msg), 422

    # semantic index (best effort - keyword retrieval still works without it)
    vecs = [None] * len(rows)
    semantic = False
    for i in range(0, len(rows), 24):
        batch = [r[2] for r in rows[i:i + 24]]
        out = embed_texts(batch)
        if not out:
            break
        for j, v in enumerate(out):
            vecs[i + j] = json.dumps([round(x, 5) for x in normalize(v)])
        semantic = True

    db = get_db()
    cur = db.execute(
        "INSERT INTO chat_files (chat_id, filename, stored_name, chunk_count) VALUES (?, ?, ?, ?)",
        (chat_id, os.path.basename(f.filename), stored, len(rows)),
    )
    fid = cur.lastrowid
    db.executemany(
        "INSERT INTO chunks (file_id, chat_id, page, idx, text, embedding) VALUES (?, ?, ?, ?, ?, ?)",
        [(fid, chat_id, pg, i, c, vecs[n]) for n, (pg, i, c) in enumerate(rows)],
    )
    db.commit()
    chars = sum(len(r[2]) for r in rows)
    return jsonify(id=fid, filename=os.path.basename(f.filename), chunk_count=len(rows),
                   chars=chars, semantic=semantic)


# --------------------------------------------------------------------------
# Retrieval
# --------------------------------------------------------------------------
STOP = set(
    "the a an and or of to in on for with is are was were be this that it as at by from "
    "what how why who when which do does did can could you me my i about into than then".split()
)
SUMMARY_RE = re.compile(
    r"\b(summar\w*|overview|outline|key points?|main points?|tl;?dr|explain (this|the|my)|"
    r"what('s| is) (this|it|in|the)|about (this|the|my)|read (this|the|my)|going on|"
    r"(file|document|pdf|doc|notes|paper|chapter|assignment))\b",
    re.I,
)


OVERVIEW_WORDS = set("summarise summarize summary overview outline key point points main explain read going file document pdf doc notes paper chapter assignment uploaded give tell show whole entire full content contents".split())


def tokens(s):
    return [w for w in re.findall(r"[a-z0-9]+", s.lower()) if w not in STOP and len(w) > 1]


def dot(a, b):
    if np is not None:
        return float(np.dot(a, b))
    return sum(x * y for x, y in zip(a, b))


def spread(rows, budget):
    """Evenly sample rows across the whole document(s) within a character budget."""
    k = max(1, budget // CHUNK_SIZE)
    if len(rows) <= k:
        return list(rows)
    picks = sorted({int(i * len(rows) / k) for i in range(k)})
    return [rows[i] for i in picks]


FOLLOWUP_RE = re.compile(r"\b(it|this|that|these|those|they|them|its|more|further|above|previous|same|also|again)\b", re.I)


def retrieval_query(db, chat_id, query):
    """Short follow-ups ("and its drawbacks?") get the previous question prepended so retrieval still works."""
    if len(tokens(query)) <= 5 or FOLLOWUP_RE.search(query) and len(tokens(query)) <= 8:
        prev = db.execute(
            "SELECT content FROM messages WHERE chat_id = ? AND role = 'user' ORDER BY id DESC LIMIT 1", (chat_id,)
        ).fetchone()
        if prev and not prev["content"].startswith("```"):
            return prev["content"][:300] + " " + query
    return query


def bm25_scores(q_terms, docs, k1=1.4, b=0.75):
    n = len(docs)
    toks = [tokens(d) for d in docs]
    avg = (sum(len(t) for t in toks) / n) or 1
    df = {}
    for t in toks:
        for w in set(t):
            df[w] = df.get(w, 0) + 1
    out = []
    for t in toks:
        tf = {}
        for w in t:
            tf[w] = tf.get(w, 0) + 1
        sc = 0.0
        for w in q_terms:
            if w in tf:
                idf = math.log(1 + (n - df[w] + 0.5) / (df[w] + 0.5))
                sc += idf * tf[w] * (k1 + 1) / (tf[w] + k1 * (1 - b + b * len(t) / avg))
        out.append(sc)
    return out


def build_context(db, chat_id, query, overview=False, budget=CONTEXT_CHARS):
    """Pick the document text the model should see.

    small docs      -> everything
    overview asks   -> chunks sampled evenly across the whole file(s)
    specific asks   -> BM25 + semantic ranks fused (RRF), neighbours of the best hits added
    """
    rows = db.execute(
        "SELECT c.id, c.file_id, c.page, c.idx, c.text, c.embedding, f.filename "
        "FROM chunks c JOIN chat_files f ON f.id = c.file_id WHERE c.chat_id = ? "
        "ORDER BY c.file_id, c.idx, c.id",
        (chat_id,),
    ).fetchall()
    if not rows:
        return [], []
    total = sum(len(r["text"]) for r in rows)
    q_text = retrieval_query(db, chat_id, query)

    if total <= min(WHOLE_DOC_CHARS, budget + 2000):
        chosen = list(rows)                       # small enough: give the model everything
    elif overview or (SUMMARY_RE.search(query) and len([t for t in tokens(query) if t not in OVERVIEW_WORDS]) <= 1):
        chosen = spread(rows, budget)             # generic request: sample the whole file
    else:
        q_terms = tokens(q_text)
        kw = bm25_scores(q_terms, [r["text"] for r in rows]) if q_terms else [0.0] * len(rows)
        sem = [0.0] * len(rows)
        if any(r["embedding"] for r in rows):
            emb = embed_texts([q_text])
            if emb:
                qv = normalize(emb[0])
                sem = [dot(qv, json.loads(r["embedding"])) if r["embedding"] else 0.0 for r in rows]
        fused = [0.0] * len(rows)
        for scores in (kw, sem):
            if not any(scores):
                continue
            order = sorted(range(len(rows)), key=lambda i: scores[i], reverse=True)
            for rank, i in enumerate(order):
                if scores[i] > 0:
                    fused[i] += 1.0 / (60 + rank)
        ranked = [i for i in sorted(range(len(rows)), key=lambda i: fused[i], reverse=True) if fused[i] > 0]
        if not ranked:
            chosen = spread(rows, budget)
        else:
            picked, seen = [], set()
            def add(i):
                if i not in seen and 0 <= i < len(rows):
                    seen.add(i)
                    picked.append(i)
            for i in ranked[:TOP_K]:
                add(i)
            for i in ranked[:3]:                   # neighbours give the surrounding explanation
                for j in (i - 1, i + 1):
                    if 0 <= j < len(rows) and rows[j]["file_id"] == rows[i]["file_id"]:
                        add(j)
            for fid in {r["file_id"] for r in rows}:   # always include each file's opening
                add(next(i for i, r in enumerate(rows) if r["file_id"] == fid))
            chosen = [rows[i] for i in picked]

    kept, used = [], 0            # keep the highest-priority chunks that fit, then restore reading order
    for r in chosen:
        if used + len(r["text"]) > budget:
            continue
        kept.append(r)
        used += len(r["text"])
    kept.sort(key=lambda r: (r["file_id"], r["idx"], r["id"]))
    out = [{"filename": r["filename"], "page": r["page"], "text": r["text"]} for r in kept]

    by_file = {}
    for c in out:
        by_file.setdefault(c["filename"], set()).add(c["page"])
    sources = [{"file": f, "pages": sorted(p)} for f, p in by_file.items()]
    return out, sources


SYSTEM_PROMPT = (
    "You are Studiora AI, a warm, precise study assistant for students. "
    "Explain step by step when useful, use Markdown for structure, and keep answers focused.\n"
    "RULES:\n"
    "1. When document excerpts are provided they are the student's own uploaded material: base your answer "
    "primarily on them and name the file (and page when known) you used.\n"
    "2. If the excerpts do not contain the answer, say so plainly first ('I couldn't find that in your uploaded "
    "documents'), then you may add general knowledge, clearly labelled as such.\n"
    "3. Never invent facts, page numbers or citations.\n"
    "4. Numbered lists must be ONE continuous list (1, 2, 3, ...). Put any sub-points as indented bullets "
    "under the number and never restart numbering.\n"
    "5. Write maths in plain text or Unicode (x², √, ≤); do not use LaTeX. Put code in fenced blocks with the language.\n"
    "6. You cannot attach files yourself. If asked for a PDF/Word file or a diagram, tell the student to ask "
    "e.g. 'Create a PDF of short notes on <topic>' or 'Draw a diagram of <topic>' so the built-in tools do it. "
    "Never invent a download link.\n"
    "7. Interactive quizzes are handled by the app: if the student wants MCQs, tell them to say "
    "'Ask me MCQ questions one by one on <topic>'. Otherwise ask questions normally and let them type answers.\n"
    "8. Treat ```mcq / ```diagram / ```docs / ```actions blocks in the history as widgets the app already showed."
)


def build_messages(db, chat_id, user_text, context):
    hist = db.execute(
        "SELECT role, content FROM messages WHERE chat_id = ? ORDER BY id DESC LIMIT ?",
        (chat_id, HISTORY_LIMIT * 2),
    ).fetchall()[::-1]
    names = [r["filename"] for r in db.execute(
        "SELECT filename FROM chat_files WHERE chat_id = ? ORDER BY id", (chat_id,))]
    system = SYSTEM_PROMPT
    if names:
        system += "\n\nFiles attached to this conversation: " + ", ".join(names) + "."
    msgs = [{"role": "system", "content": system}]
    msgs += [{"role": r["role"], "content": compact_history(r["content"])} for r in hist]
    if context:
        blocks = "\n\n".join(f"[{c['filename']} · page {c['page']}]\n{c['text']}" for c in context)
        content = (
            "Here are excerpts from the student's uploaded documents. Use them to answer.\n\n"
            f"<documents>\n{blocks}\n</documents>\n\nQuestion: {user_text}"
        )
    else:
        content = user_text
    msgs.append({"role": "user", "content": content})
    return msgs


