GENERIC_WORDS = set(
    "a an the of on for about from to in with and or please pls me my i can you could would give make create generate prepare "
    "write produce build draw show download need want some short brief quick detailed complete full pdf word docx doc document "
    "file notes note summary summarise summarize revision study guide cheat sheet handout diagram diagrams diagrammatic "
    "representation flowchart flow chart mind map concept block architecture visual visualise visualize explanation explain "
    "mcq mcqs questions question quiz test multiple choice one by at time ask uploaded attached this that it pages page "
    "downloadable format using as into then also".split()
)


def clean_topic(text):
    """Best-effort topic out of a request like 'create a pdf of short notes on process scheduling'."""
    t = re.sub(r"\s+", " ", text.strip())
    m = None
    for pat in (r"\b(?:on|about|regarding|covering|related to)\s+(.+)$", r"\bof\s+(.+)$", r"\bfor\s+(.+)$"):
        m = re.search(pat, t, re.I)
        if m:
            break
    cand = m.group(1) if m else t
    words = [w for w in re.findall(r"[\w'+#./-]+", cand)]
    while words and words[0].lower() in GENERIC_WORDS:
        words.pop(0)
    while words and words[-1].lower() in GENERIC_WORDS:
        words.pop()
    topic = " ".join(words).strip(" .,-")
    if m and len([w for w in words if w.lower() not in GENERIC_WORDS]) == 0:
        return ""
    return topic[:120]


def compact_history(content):
    """Fenced widgets are big JSON; the model only needs a one-line reminder of them."""
    def rep(m):
        lang, body = m.group(1), m.group(2)
        try:
            d = json.loads(body)
        except ValueError:
            return f"[{lang} widget]"
        if lang == "diagram":
            return f"[diagram shown: {d.get('title', '')}]"
        if lang == "mcq":
            return f"[MCQ {d.get('n', '')} shown: {d.get('question', '')}]"
        if lang == "docs":
            return "[document files generated: " + ", ".join(x.get("filename", "") for x in d) + "]"
        return ""
    return re.sub(r"```(diagram|mcq|docs|actions)\n(.*?)\n```", rep, content, flags=re.S)


def fence(lang, payload):
    return f"```{lang}\n{json.dumps(payload, ensure_ascii=False)}\n```"


def parse_fence(content, lang):
    m = re.match(r"\s*(?:[^`]*?)```" + lang + r"\n(.*?)\n```", content or "", re.S)
    if not m:
        return None
    try:
        return json.loads(m.group(1))
    except ValueError:
        return None


def chat_file_names(db, chat_id):
    return [r["filename"] for r in db.execute("SELECT filename FROM chat_files WHERE chat_id = ? ORDER BY id", (chat_id,))]


def prev_assistant_text(db, chat_id, limit=3500):
    row = db.execute(
        "SELECT content FROM messages WHERE chat_id = ? AND role = 'assistant' ORDER BY id DESC LIMIT 1", (chat_id,)
    ).fetchone()
    return compact_history(row["content"])[:limit] if row else ""


def source_block(context):
    return "\n\n".join(f"[{c['filename']} · page {c['page']}]\n{c['text']}" for c in context)


# ---- greeting / small talk --------------------------------------------------
def greeting_reply(db, chat_id, hour):
    u = db.execute("SELECT display_name FROM users WHERE id = ?", (session["user_id"],)).fetchone()
    name = (u["display_name"] if u else "there").replace("_", " ").replace(".", " ").title()
    hour = hour if isinstance(hour, int) and 0 <= hour <= 23 else datetime.now().hour
    part = "Good morning" if hour < 12 else "Good afternoon" if hour < 17 else "Good evening"
    files = chat_file_names(db, chat_id)
    if files:
        shown = ", ".join(f"**{f}**" for f in files[:3]) + (f" and {len(files) - 3} more" if len(files) > 3 else "")
        text = (f"{part}, **{name}**! 👋 Welcome back to your study space.\n\n"
                f"I've read {shown} and I'm ready whenever you are. What would you like to do?")
        acts = [{"label": "Summarise my file", "send": "Give me a clear summary of my uploaded file"},
                {"label": "Short notes (PDF)", "send": "Create a PDF of short notes from my uploaded file"},
                {"label": "Quiz me (MCQ)", "send": "Ask me MCQ questions one by one from my uploaded file"},
                {"label": "Draw a diagram", "send": "Draw a diagram of the main ideas in my uploaded file"}]
    else:
        text = (f"{part}, **{name}**! 👋 I'm Studiora, your study companion.\n\n"
                "Drop in your notes (PDF, Word, TXT, MD or CSV) and I'll read them, or just tell me what you're "
                "studying and we'll start from there.")
        acts = [{"label": "Explain a topic", "fill": "Explain "},
                {"label": "Short notes (PDF)", "fill": "Create a PDF of short notes on "},
                {"label": "Quiz me (MCQ)", "fill": "Ask me MCQ questions one by one on "},
                {"label": "Draw a diagram", "fill": "Draw a diagram of "}]
    return text + "\n\n" + fence("actions", acts)


def instant_work(text):
    def work(job):
        job.push(text)
    return work


# ---- diagrams ----------------------------------------------------------------
DIAGRAM_PROMPT = """You are designing a clear block diagram that helps a student understand a topic at a glance.

Topic: {topic}
{source}
Return ONLY a JSON object in exactly this shape:
{{"title": "short title", "groups": [{{"id": "g1", "label": "Layer or category name", "nodes": [{{"id": "n1", "label": "Box name", "note": "tiny hint (optional)"}}]}}], "edges": [{{"from": "n1", "to": "n2", "label": "verb or data"}}]}}

Rules:
- 3 to 5 groups, ordered top to bottom in the order information or control flows (for example Client Layer, Application, AI Layer, Data Layer).
- 2 to 4 nodes per group. Box labels: at most 4 words. Notes: at most 5 words.
- Every node belongs to exactly one group and has a unique id.
- 6 to 14 edges showing flow or relationships between nodes, mostly between different groups. Edge labels: at most 3 words.
- {grounding}
"""


def make_diagram(topic, context, hint, model):
    grounding = ("Use only facts found in the source material above." if context
                 else "Use accurate, widely accepted knowledge about the topic.")
    src = f"\nSource material from the student's files:\n{source_block(context)}\n" if context else ""
    if hint:
        src += f"\nMain ideas to cover:\n{hint}\n"
    last = None
    for _ in range(2):
        try:
            data = llm_json(DIAGRAM_PROMPT.format(topic=topic, source=src, grounding=grounding), model,
                            num_predict=1800)
            return dg.layout(data)
        except (ValueError, KeyError) as exc:
            last = exc
    raise ValueError(f"I couldn't build a usable diagram ({last})")


def diagram_work(model, topic, context, sources_note):
    def work(job):
        job.set_status("Sketching your diagram…")
        lay = make_diagram(topic, context, "", model)
        if job.cancel:
            return
        lead = f"Here's a diagram of **{lay['title']}**"
        if sources_note:
            lead += f", built from {sources_note}"
        job.push(lead + ". Use the zoom buttons, scroll wheel or drag to explore it.\n\n" + fence("diagram", lay))
    return work


# ---- MCQ ---------------------------------------------------------------------
MCQ_PROMPT = """Write ONE multiple-choice question that tests understanding (not trivia) for a student.

Topic: {topic}
{source}{asked}
Return ONLY a JSON object in exactly this shape:
{{"question": "...", "options": ["...", "...", "...", "..."], "answer": 0, "explanation": "1-2 sentences on why the right option is right"}}

Rules: exactly 4 options without letters or numbers in front, exactly one correct ("answer" is its 0-based index), plausible wrong options, {grounding}
"""


def normalize_mcq(data):
    q = re.sub(r"\s+", " ", str(data.get("question") or "")).strip()
    opts = [re.sub(r"^\s*(?:[A-Da-d][).:]|\d[).:])\s*", "", str(o)).strip() for o in (data.get("options") or [])]
    opts = [o for o in opts if o]
    if not q or len(opts) < 4 or len(set(o.lower() for o in opts[:4])) < 4:
        raise ValueError("incomplete question")
    opts = opts[:4]
    ans = data.get("answer")
    if isinstance(ans, str):
        ans = "abcd".find(ans.strip().lower()[:1]) if ans.strip()[:1].isalpha() else int(ans)
    if not isinstance(ans, int) or not 0 <= ans < 4:
        raise ValueError("bad answer index")
    order = random.sample(range(4), 4)               # models love putting the answer first: shuffle
    return {"question": q[:400], "options": [opts[i] for i in order], "answer": order.index(ans),
            "explanation": re.sub(r"\s+", " ", str(data.get("explanation") or "")).strip()[:420]}


def mcq_work(model, topic, n, total, context, asked):
    def work(job):
        job.set_status(f"Writing question {n}…")
        grounding = ("base it only on the source material." if context else "use accurate, standard knowledge.")
        src = f"Source material from the student's files:\n{source_block(context)}\n\n" if context else ""
        prev = ("Questions already asked (do not repeat them):\n- " + "\n- ".join(asked) + "\n") if asked else ""
        err = None
        for _ in range(3):
            try:
                q = normalize_mcq(llm_json(MCQ_PROMPT.format(topic=topic, source=src, asked=prev, grounding=grounding),
                                           model, num_predict=700, temperature=0.7, tries=1))
                break
            except (ValueError, KeyError, TypeError) as exc:
                err = exc
        else:
            raise ValueError(f"I couldn't write a usable question ({err})")
        intro = "Let's go! Tap the answer you think is right. 🎯\n\n" if n == 1 else ""
        job.push(intro + fence("mcq", {"topic": topic, "n": n, "total": total, **q}))
    return work


def quiz_session(db, chat_id):
    """MCQ messages of the quiz currently in progress (back to its question 1)."""
    rows = db.execute(
        "SELECT id, content, meta FROM messages WHERE chat_id = ? AND role = 'assistant' AND content LIKE '%```mcq%' "
        "ORDER BY id DESC", (chat_id,)).fetchall()
    out = []
    for r in rows:
        p = parse_fence(r["content"], "mcq")
        if not p:
            continue
        out.append((p, json.loads(r["meta"]) if r["meta"] else {}))
        if p.get("n") == 1:
            break
    return out[::-1]


def quiz_summary(session_items):
    right = sum(1 for p, m in session_items if m.get("pick") == p["answer"])
    answered = sum(1 for p, m in session_items if "pick" in m)
    total = len(session_items)
    pct = round(100 * right / total) if total else 0
    verdict = ("Outstanding! 🌟" if pct >= 85 else "Solid work! 💪" if pct >= 60 else "Good start — let's review! 📚")
    lines = [f"## Quiz complete\n\n**Score: {right} / {total}** ({pct}%) — {verdict}\n"]
    if answered < total:
        lines.append(f"_{total - answered} unanswered._\n")
    lines.append("| # | Question | Your answer | Result |\n|---|---|---|---|")
    for p, m in session_items:
        pick = m.get("pick")
        mine = p["options"][pick] if isinstance(pick, int) else "—"
        res = "✅" if pick == p["answer"] else f"❌ → {p['options'][p['answer']]}"
        lines.append(f"| {p['n']} | {p['question'][:70]} | {mine[:40]} | {res} |")
    lines.append("\nWant another round, or a PDF of short notes on what you missed?")
    return "\n".join(lines)


# ---- documents (PDF / Word) -------------------------------------------------
DOC_PROMPT = """You are an expert teacher writing {kind} for a student.

Topic / request: {topic}
Length: {n} sections. {depth}
{source}
Write accurate, well-organised, exam-ready content. For each section choose ONE body format:
- "content": a paragraph of prose (definitions, reasoning, examples)
- "points": an array of full-sentence bullet points
- "table": an array of rows (first row = header), only when the content is naturally a comparison
Also give every section a "gist" (one short sentence, max 14 words) and, where useful, a "tip" (an exam tip or common mistake).
Mix the formats across sections. Do not add a References section. {grounding}

Respond with ONLY valid JSON (escape double quotes inside strings, no trailing commas) in this shape:
{{"title": "Clear Title", "summary": "2-3 sentence overview", "key_takeaways": ["...", "..."],
  "sections": [{{"heading": "...", "gist": "...", "content": "...", "tip": "..."}},
               {{"heading": "...", "gist": "...", "points": ["...", "..."]}},
               {{"heading": "...", "gist": "...", "table": [["Col A", "Col B"], ["...", "..."]]}}]}}
"""


def doc_options(text):
    t = text.lower()
    fmts = []
    if re.search(r"\bpdf\b", t):
        fmts.append("pdf")
    if re.search(r"\b(docx|word)\b|\.doc\b", t):
        fmts.append("docx")
    if re.search(r"\bboth\b", t):
        fmts = ["pdf", "docx"]
    fmts = fmts or ["pdf"]
    m = re.search(r"(\d+)\s*(?:-|\s)?\s*pages?", t)
    if m:
        n = max(3, min(14, int(m.group(1)) + 1))
        depth = "detailed"
    elif re.search(r"\b(short|brief|quick|concise|one[- ]page|cheat\s*sheet)\b", t):
        n, depth = 5, "short"
    elif re.search(r"\b(detailed|comprehensive|full|complete|in[- ]depth)\b", t):
        n, depth = 10, "detailed"
    else:
        n, depth = 7, "standard"
    kind = ("a cheat sheet" if "cheat" in t else "revision notes" if "revision" in t else "a summary" if "summar" in t
            else "an assignment-style report" if re.search(r"assignment|report", t) else "study notes")
    depth_text = {
        "short": "Keep it concise: paragraphs of about 50-90 words, 4-6 bullet points, tables of 3-4 rows.",
        "standard": "Paragraphs of about 100-160 words, 5-8 substantive bullet points, tables of 4-5 rows.",
        "detailed": "Be thorough: paragraphs of 150-250 words, 6-9 substantive bullet points, tables of 5-6 rows.",
    }[depth]
    return fmts, n, kind, depth_text


def doc_work(user_id, chat_id, model, request_text, topic, context, prior, files_note):
    fmts, n, kind, depth = doc_options(request_text)

    def work(job):
        job.set_status("Reading your material…" if context else "Planning your document…")
        if context:
            source = f"\nSOURCE MATERIAL from the student's own files:\n{source_block(context)}\n"
            grounding = "Base every section on the source material; do not add facts it does not support."
        elif prior:
            source = f"\nBase the document on this earlier conversation content:\n{prior}\n"
            grounding = "Stay faithful to that content."
        else:
            source, grounding = "", "Use accurate, widely accepted knowledge. Do not invent statistics or sources."
        job.set_status("Writing the sections…")
        prompt = DOC_PROMPT.format(kind=kind, topic=topic, n=n, depth=depth, source=source, grounding=grounding)
        doc = None
        for _ in range(2):
            try:
                data = llm_json(prompt, model, num_predict=DOC_MAX_TOKENS, num_ctx=DOC_NUM_CTX, tries=1)
                doc = docgen.normalize_doc(data, fallback_title=topic.title() or "Study Notes")
                break
            except (ValueError, KeyError) as exc:
                err = exc
        if doc is None:
            raise ValueError(f"I couldn't structure that document ({err})")
        if job.cancel:
            return

        job.set_status("Drawing the concept map…")
        hint = "\n".join(f"- {s['heading']}: {s['gist']}" for s in doc["sections"])
        try:
            lay = make_diagram(doc["title"], context if context else [], hint, model)
        except Exception:  # noqa: BLE001 - the deterministic map always works
            lay = dg.layout(dg.from_sections(doc["title"], _clip_note(doc["summary"]),
                                             [(s["heading"], s["gist"]) for s in doc["sections"]]))
        job.set_status("Building " + " and ".join(f.upper() if f == "pdf" else "Word" for f in fmts) + "…")
        udir = os.path.join(GENERATED_DIR, f"user_{user_id}")
        os.makedirs(udir, exist_ok=True)
        img = dg.render_png(lay, "light", 2)
        png = os.path.join(udir, f"_map_{uuid.uuid4().hex[:8]}.png")
        img.save(png)
        base = re.sub(r"[^A-Za-z0-9]+", "_", doc["title"]).strip("_")[:60] or "Study_Notes"
        made = []
        conn = thread_db()
        try:
            for fmt in fmts:
                stored = f"{base}_{uuid.uuid4().hex[:6]}.{fmt}"
                path = os.path.join(udir, stored)
                if fmt == "pdf":
                    docgen.build_pdf(doc, path, png, img.size)
                else:
                    docgen.build_docx(doc, path, png)
                cur = conn.execute(
                    "INSERT INTO generated_documents (user_id, chat_id, title, fmt, filename, stored, size) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?)",
                    (user_id, chat_id, doc["title"], fmt, f"{base}.{fmt}", stored, os.path.getsize(path)))
                made.append({"id": cur.lastrowid, "title": doc["title"], "fmt": fmt, "filename": f"{base}.{fmt}",
                             "size": os.path.getsize(path)})
            conn.commit()
        finally:
            conn.close()
            try:
                os.remove(png)
            except OSError:
                pass
        lead = (f"I've created **{doc['title']}** — {len(doc['sections'])} sections with an at-a-glance box, a "
                f"concept map and key-concept boxes" + (f", based on {files_note}" if files_note else "") + ".")
        job.push(lead + "\n\n" + fence("docs", made) + "\n\nHere's the concept map from the document:\n\n" + fence("diagram", lay))
    return work


def _clip_note(s):
    return re.sub(r"\s+", " ", s or "")[:34]


DOC_HELP = ("I can turn your material into a **PDF or Word** study document with an at-a-glance box, a concept-map "
            "diagram and key-concept boxes — but I need something to base it on.\n\n"
            "Upload a file, or tell me the topic, for example:\n\n"
            "- *Create a PDF of short notes on process scheduling*\n"
            "- *Make a Word document summarising my uploaded file*")


# --------------------------------------------------------------------------
# Chat: start a job, attach to its stream, stop it
# --------------------------------------------------------------------------
@app.post("/api/chats/<int:chat_id>/chat")
@login_required
def chat(chat_id):
    chat_row = own_chat(chat_id)
    if not chat_row:
        return jsonify(error="Not found"), 404
    data = request.get_json(silent=True) or {}
    text = (data.get("message") or "").strip()
    if not text:
        return jsonify(error="Empty message"), 400
    if chat_id in JOBS:
        return jsonify(error="This chat is still answering"), 409
    model = (data.get("model") or "").strip()
    if not re.fullmatch(r"[\w.:/\-]{1,80}", model or ""):
        model = CHAT_MODEL

    db = get_db()
    uid = session["user_id"]
    attachments = []
    ids = [int(i) for i in (data.get("file_ids") or []) if str(i).isdigit()]
    if ids:
        marks = ",".join("?" * len(ids))
        attachments = [
            {"id": r["id"], "name": r["filename"]}
            for r in db.execute(
                f"SELECT id, filename FROM chat_files WHERE chat_id = ? AND id IN ({marks})",
                [chat_id, *ids],
            )
        ]
    files = chat_file_names(db, chat_id)
    files_note = ", ".join(f"**{f}**" for f in files[:2]) if files else ""

    # ---- decide what kind of request this is
    kind, status, work, sources = "chat", "", None, []
    last_ai = db.execute(
        "SELECT content FROM messages WHERE chat_id = ? AND role = 'assistant' ORDER BY id DESC LIMIT 1", (chat_id,)
    ).fetchone()
    in_quiz = bool(last_ai and last_ai["content"].lstrip().startswith(("```mcq", "Let's go! Tap")))
    hour = data.get("hour") if isinstance(data.get("hour"), int) else None

    if GREET_RE.match(text):
        kind, work = "instant", instant_work(greeting_reply(db, chat_id, hour))
    elif THANKS_RE.match(text) and not in_quiz:
        kind, work = "instant", instant_work("You're welcome! 😊 Ask me anything else, or say *'quiz me'* when you want to practise.")
    elif in_quiz and END_RE.search(text):
        kind, work = "instant", instant_work(quiz_summary(quiz_session(db, chat_id)))
    elif in_quiz and NEXT_RE.match(text):
        items = quiz_session(db, chat_id)
        cur = items[-1][0] if items else {}
        n, total = cur.get("n", 0) + 1, cur.get("total")
        if total and n > total:
            kind, work = "instant", instant_work(quiz_summary(items))
        else:
            topic = cur.get("topic") or "the topic"
            ctx, sources = build_context(db, chat_id, topic, overview=not topic or topic == "your uploaded files")
            kind, status = "mcq", f"Writing question {n}…"
            work = mcq_work(model, topic, n, total, ctx, [p["question"] for p, _ in items][-12:])
    elif MCQ_RE.search(text) and ONEBYONE_RE.search(text):
        topic = clean_topic(re.sub(r"one[- ]by[- ]one|one at a time", "", text, flags=re.I))
        if not topic and not files:
            kind, work = "instant", instant_work("Happy to quiz you! **What topic?** Say for example: *Ask me MCQ questions one by one on photosynthesis* — or upload your notes and I'll quiz you from them.")
        else:
            m = re.search(r"(\d{1,2})\s*(?:mcqs?|questions?|qs?)\b", text, re.I)
            total = min(30, int(m.group(1))) if m else None
            if not topic or FILE_REF_RE.search(text):
                topic = topic if topic and not FILE_REF_RE.search(topic) else "your uploaded files"
            ctx, sources = build_context(db, chat_id, topic if topic != "your uploaded files" else "",
                                         overview=topic == "your uploaded files")
            kind, status = "mcq", "Writing question 1…"
            work = mcq_work(model, topic, 1, total, ctx, [])
    elif DOC_RE.search(text) or (DOC_FMT_RE.search(text) and DOC_THING_RE.search(text)):
        topic = clean_topic(text)
        prior = ""
        use_files = bool(files) and (not topic or FILE_REF_RE.search(text) or True)
        if not topic and re.search(r"\b(above|previous|earlier|that|this|it)\b", text, re.I) and not files:
            prior = prev_assistant_text(db, chat_id)
        if not files and not topic and not prior:
            kind, work = "instant", instant_work(DOC_HELP)
        else:
            ctx = []
            if use_files:
                ctx, sources = build_context(db, chat_id, topic, overview=not topic or bool(FILE_REF_RE.search(text)),
                                             budget=CONTEXT_CHARS)
            if not topic:
                topic = (os.path.splitext(files[0])[0].replace("_", " ") if files else "the conversation so far")
            kind, status = "doc", "Reading your material…" if ctx else "Planning your document…"
            work = doc_work(uid, chat_id, model, text, topic, ctx, prior, files_note if ctx else "")
    elif DIAGRAM_RE.search(text) and DIAGRAM_VERB_RE.search(text):
        topic = clean_topic(text)
        if not topic and not files:
            kind, work = "instant", instant_work("Sure — **what should the diagram show?** For example: *Draw a diagram of the TCP three-way handshake*, or upload a file and ask me to diagram it.")
        else:
            from_file = bool(files) and (not topic or FILE_REF_RE.search(text))
            ctx = []
            if from_file:
                ctx, sources = build_context(db, chat_id, topic, overview=True, budget=7000)
            topic = topic or (os.path.splitext(files[0])[0].replace("_", " ") if files else "")
            kind, status = "diagram", "Sketching your diagram…"
            work = diagram_work(model, topic, ctx, files_note if ctx else "")

    if work is None:  # ordinary answer
        context, sources = build_context(db, chat_id, text)
        work = chat_work(build_messages(db, chat_id, text, context), model)

    db.execute(
        "INSERT INTO messages (chat_id, role, content, attachments) VALUES (?, 'user', ?, ?)",
        (chat_id, text, json.dumps(attachments) if attachments else None),
    )
    title = chat_row["title"]
    if title == "New chat":
        title = re.sub(r"\s+", " ", text)[:40] + ("…" if len(text) > 40 else "")
        db.execute("UPDATE chats SET title = ? WHERE id = ?", (title, chat_id))
    db.execute("UPDATE chats SET updated_at = CURRENT_TIMESTAMP WHERE id = ?", (chat_id,))
    db.commit()

    job = Job(chat_id, sources, kind, status)
    with JOBS_LOCK:
        JOBS[chat_id] = job
    threading.Thread(target=execute_job, args=(job, work), daemon=True).start()
    return jsonify(ok=True, title=title, sources=sources, kind=kind, status=status)


@app.get("/api/chats/<int:chat_id>/stream")
@login_required
def stream(chat_id):
    if not own_chat(chat_id):
        return jsonify(error="Not found"), 404
    job = JOBS.get(chat_id)

    @stream_with_context
    def generate():
        if not job:
            yield sse("done", {"missing": True})
            return
        yield sse("meta", {"sources": job.sources, "kind": job.kind, "status": job.status})
        pos, last_status = 0, job.status
        while True:
            with job.cond:
                if pos == len(job.text) and not job.done and job.status == last_status:
                    job.cond.wait(timeout=15)
                chunk = job.text[pos:]
                done = job.done
                status = job.status
            if status != last_status:
                last_status = status
                yield sse("status", {"status": status})
            if chunk:
                pos += len(chunk)
                yield sse("token", {"t": chunk})
            elif done:
                break
            elif status == last_status:
                yield ": keep-alive\n\n"
        yield sse("done", {"id": job.message_id})

    return Response(
        generate(),
        mimetype="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )


@app.post("/api/chats/<int:chat_id>/stop")
@login_required
def stop(chat_id):
    if not own_chat(chat_id):
        return jsonify(error="Not found"), 404
    job = JOBS.get(chat_id)
    if job:
        job.cancel = True
    return jsonify(ok=True)


