@app.post("/api/chats/<int:chat_id>/messages/<int:msg_id>/pick")
@login_required
def mcq_pick(chat_id, msg_id):
    if not own_chat(chat_id):
        return jsonify(error="Not found"), 404
    db = get_db()
    row = db.execute("SELECT content, meta FROM messages WHERE id = ? AND chat_id = ? AND role = 'assistant'",
                     (msg_id, chat_id)).fetchone()
    q = parse_fence(row["content"], "mcq") if row else None
    if not q:
        return jsonify(error="Not a quiz question"), 404
    pick = (request.get_json(silent=True) or {}).get("pick")
    if not isinstance(pick, int) or not 0 <= pick < len(q["options"]):
        return jsonify(error="Bad option"), 400
    meta = json.loads(row["meta"]) if row["meta"] else {}
    if "pick" not in meta:                      # first answer counts
        meta["pick"] = pick
        db.execute("UPDATE messages SET meta = ? WHERE id = ?", (json.dumps(meta), msg_id))
        db.commit()
    return jsonify(ok=True, pick=meta["pick"], correct=meta["pick"] == q["answer"], answer=q["answer"])


