@app.post("/api/diagram/png")
@login_required
def diagram_png():
    import io
    try:
        lay = dg.layout((request.get_json(silent=True) or {}))
    except (ValueError, KeyError, TypeError):
        return jsonify(error="Bad diagram"), 400
    buf = io.BytesIO()
    dg.render_png(lay, "dark", 2, True).save(buf, "PNG")
    buf.seek(0)
    name = re.sub(r"[^A-Za-z0-9]+", "_", lay["title"]).strip("_") or "diagram"
    return send_file(buf, mimetype="image/png", as_attachment=True, download_name=f"{name}.png")


